            if (earned && selfa >= 55) insights.push(T('insight_earned'));
            else if (ds.rankPulled && plays.response !== 'rank') insights.push(T('insight_rank'));
            else if (ds.abdicated && !ds.rankPulled) insights.push(T('insight_abdicate'));
            else if (!made.length) insights.push(T('insight_short'));
            const tpInfo = this._turningPoint(ds, made);
            made.forEach(function(m) { if (m.key !== tpInfo.causeKey) insights.push(T(m.key)); });
            // what worked, from the plays actually made
            if (plays.response === 'merits') insights.push(T('ins_merits'));
            if (plays.frame === 'consent' && plays.approach === 'acknowledge') insights.push(T('ins_veteran'));
            if (plays.process === 'surface') insights.push(T('ins_surface'));
            if (credibility < 100) insights.push(T('ins_cred_a') + ' ' + credibility + ' ' + T('ins_cred_b'));

            if (follower < 45) insights.push(T('insight_lowfollower'));
            if (selfa < 40) insights.push(T('insight_lowself'));
            if (!ds.contractSet) insights.push(T('insight_nocontract'));
            if (ds.credibility <= 40) insights.push(T('insight_credburn'));
            if (earned && ds.contractSet && selfa >= 60) insights.push(T('insight_lasts'));
            insights = insights.slice(0, 5);

            return {
                trust: trust,
                decision: decision,
                follower: follower,
                self: selfa,
                earned: earned,
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                performanceKey: performanceKey,
                rankPulled: ds.rankPulled,
                abdicated: ds.abdicated,
                performance: performanceKey,
                performanceLabel: performanceLabel,
                outcomeScore: composite,
                processScore: credibility,
                turningPoint: tpInfo.text,
                questions: [T('dq_1'), T('dq_2'), T('dq_3')],
                insights: insights
            };
        }

        // v1.2.0: the mapped plays of this run, in round order. hit = the round where the cost lands.
        _mistakesMade(ds) {
            var p = (ds && ds.plays) || {};
            var out = [];
            if (p.response === 'rank') out.push({ key: 'mk_rank', round: 2, hit: 2 });
            if (p.frame === 'performance') out.push({ key: 'mk_perf', round: 3, hit: 3 });
            if (p.approach === 'overpromise') out.push({ key: 'mk_promise', round: 3, hit: 4 });
            if (p.process === 'overquestion') out.push({ key: 'mk_open', round: 4, hit: 4 });
            if (p.director === 'confidence') out.push({ key: 'mk_certainty', round: 4, hit: 4 });
            return out;
        }

        // v1.2.0: the round where the overall score moved least in the player's favour, with the play behind it.
        _turningPoint(ds, made) {
            var h = (ds && ds.compHistory) || [];
            if (h.length < 2) return { text: '', causeKey: '' };
            var T = function(k) { return window.mySimulation.t(k); };
            var worst = 1, best = 1, i;
            for (i = 1; i < h.length; i++) {
                if (h[i] - h[i - 1] < h[worst] - h[worst - 1]) worst = i;
                if (h[i] - h[i - 1] > h[best] - h[best - 1]) best = i;
            }
            var fell = (h[worst] - h[worst - 1]) < 0;
            var cause = (made || []).filter(function(m) { return m.hit === worst; })[0];
            var r = (fell || cause) ? worst : best;
            var text = T('tp_round') + ' ' + r + ': ' + T('tp_from') + ' ' + h[r - 1] + ' ' + T('tp_to') + ' ' + h[r] + '. ';
            if (fell || cause) text += cause ? T(cause.key) : T('tp_fell');
            else text += T('tp_best');
            return { text: text, causeKey: (cause ? cause.key : '') };
        }

        formatCompletionMessage(summary) {
            var T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            var s = summary || {};
            var score = (typeof s.overallScore === 'number') ? s.overallScore
                : (typeof s.composite === 'number' ? s.composite : 0);
            var grade = s.performanceLabel || (s.performanceKey ? T(s.performanceKey) : '');
            var qs = Array.isArray(s.questions) ? s.questions : [];
            var qItems = qs.map(function(t) { return '<li>' + t + '</li>'; }).join('');
            var sub = ''
                + '<div class="authoritysim-cm-sub"><span class="authoritysim-cm-sub-l">' + T('cm_outcome') + '</span> <strong>' + Math.round(s.outcomeScore || 0) + '/100</strong>'
                + ' <span class="authoritysim-cm-sub-sep">·</span> <span class="authoritysim-cm-sub-l">' + T('cm_process') + '</span> <strong>' + Math.round(s.processScore || 0) + '/100</strong></div>';
            var tp = s.turningPoint
                ? '<div class="authoritysim-cm-insights-title">' + T('cm_turning') + '</div><p class="authoritysim-cm-turning">' + s.turningPoint + '</p>'
                : '';
            var qBlock = qItems
                ? '<div class="authoritysim-cm-insights-title">' + T('cm_questions') + '</div><ol class="authoritysim-cm-questions">' + qItems + '</ol>'
                : '';
            var ok = !!s.earned;
            var badge = ok
                ? '<span class="authoritysim-cm-badge authoritysim-cm-yes">' + T('cm_met') + '</span>'
                : '<span class="authoritysim-cm-badge authoritysim-cm-no">' + T('cm_missed') + '</span>';
            var failBadge = (s.rankPulled || s.abdicated)
                ? '<span class="authoritysim-cm-badge authoritysim-cm-warn">' + T('cm_failstate_badge') + '</span>'
                : '';
            var insights = Array.isArray(s.insights) ? s.insights : [];
            var items = insights.map(function(t) { return '<li>' + t + '</li>'; }).join('');
            var metrics = ''
                + '<div class="authoritysim-cm-metric"><span class="authoritysim-cm-mv">' + Math.round(s.trust || 0) + '</span><span class="authoritysim-cm-ml">' + T('cm_m_trust') + '</span></div>'
                + '<div class="authoritysim-cm-metric"><span class="authoritysim-cm-mv">' + Math.round(s.decision || 0) + '</span><span class="authoritysim-cm-ml">' + T('cm_m_decision') + '</span></div>'
                + '<div class="authoritysim-cm-metric"><span class="authoritysim-cm-mv">' + Math.round(s.follower || 0) + '</span><span class="authoritysim-cm-ml">' + T('cm_m_follower') + '</span></div>'
                + '<div class="authoritysim-cm-metric"><span class="authoritysim-cm-mv">' + Math.round(s.self || 0) + '</span><span class="authoritysim-cm-ml">' + T('cm_m_self') + '</span></div>';
            return ''
                + '<div class="authoritysim-completion">'
                +   '<div class="authoritysim-cm-head">'
                +     '<div class="authoritysim-cm-score">' + score + '<span class="authoritysim-cm-score-max">/100</span></div>'
                +     '<div class="authoritysim-cm-grade">' + grade + ' ' + badge + failBadge + '</div>'
                +   '</div>'
                +   sub
                +   '<div class="authoritysim-cm-metrics">' + metrics + '</div>'
                +   tp
                +   '<div class="authoritysim-cm-insights-title">' + T('cm_debrief') + '</div>'
                +   '<ul class="authoritysim-cm-insights">' + items + '</ul>'
                +   qBlock
                + '</div>';
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.rankPulled && state.currentPeriod >= 2) return window.mySimulation.t(`hint_rank`);
            if (ds.abdicated && state.currentPeriod >= 2) return window.mySimulation.t(`hint_abdicate`);
            if (ds.follower < 35) return window.mySimulation.t(`hint_follower`);
            if (ds.self < 35) return window.mySimulation.t(`hint_self`);
            if (state.currentPeriod >= 3 && ds.trust < 45) return window.mySimulation.t(`hint_behind`);
            if (ds.trust >= this.TRUST_TARGET && ds.follower >= 60 && ds.self >= 55) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.trust`, label: `Trust`, i18nKey: `col_trust`, formatter: (v) => Math.round(v) },
                { key: `results.follower`, label: `Follower`, i18nKey: `col_follower`, formatter: (v) => Math.round(v) },
                { key: `results.self`, label: `Self-Aware`, i18nKey: `col_self`, formatter: (v) => Math.round(v) }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);
            const chartEl = document.getElementById('authorityChart');
            const dsNow = (window.mySimulation && window.mySimulation.state && window.mySimulation.state.domainState) || null;
            if (chartEl && dsNow) {
                chartEl.setAttribute('role', 'img');
                chartEl.setAttribute('aria-label', t('legend_trust') + ' ' + Math.round(dsNow.trust) + ', ' + t('legend_decision') + ' ' + Math.round(dsNow.decision) + ', ' + t('legend_follower') + ' ' + Math.round(dsNow.follower) + ', ' + t('legend_self') + ' ' + Math.round(dsNow.self) + '. ' + t('chart_alt'));
            }

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

        getTranslations() {
            return {
                en: {
                    title:                  `Earning Authority`,
                    subtitle:               `You are Camille Roche. On Friday you were the strongest engineer on the Helios squad; today you lead the eleven engineers you sat beside last week, including the skeptic who will test you in the first stand-up and the veteran who was passed over for your job. You have five working days to a design freeze worth €3.2M, with your skip-level director in the room on Friday. Four of the last six squad leads promoted from within did not last a year.`,
                    header_tag:             `Monday 15 June 2026 · Voltaris Systèmes SAS, Lyon · Design freeze due Friday 19 June`,
